-- Whole gearboxes and transfer boxes moved in go by pallet, like the rest of the category.
UPDATE products SET shipping = 'PALLET'
WHERE category_id = 'gearboxes' AND shipping <> 'PALLET'
  AND name ~* 'gearbox|transfer (box|case)' AND name !~* 'cooler|motor|mount|pipe|module|selector';
